examples.template:
MonarchAiSourceList(
    [
        MonarchAiSourceListItem(MonarchAiSourcePart(id: {{sources.0.id}}, title: {{sources.0.title}}, url: {{sources.0.url}}, kind: {{sources.0.kind|case}}, product: {{sources.0.product}}), snippet: {{sources.0.snippet}}),
        MonarchAiSourceListItem(MonarchAiSourcePart(id: {{sources.1.id}}, title: {{sources.1.title}}, url: {{sources.1.url}}, kind: {{sources.1.kind|case}}), snippet: {{sources.1.snippet}}),
        MonarchAiSourceListItem(MonarchAiSourcePart(id: {{sources.2.id}}, title: {{sources.2.title}}, kind: {{sources.2.kind|case}}, product: {{sources.2.product}}), isUsed: {{sources.2.used}}),
        MonarchAiSourceListItem(MonarchAiSourcePart(id: {{sources.3.id}}, title: {{sources.3.title}}, kind: {{sources.3.kind|case}}), isUsed: {{sources.3.used}}, snippet: {{sources.3.snippet}}),
    ],
    onOpen: { _ in }
)

examples.code:
MonarchAiSourceList(
    [
        MonarchAiSourceListItem(MonarchAiSourcePart(id: "s1", title: "Team handbook", url: "https://example.com/handbook", kind: .doc, product: "Docs"), snippet: "Requests are answered within two working days."),
        MonarchAiSourceListItem(MonarchAiSourcePart(id: "s2", title: "Support policy", url: "https://example.com/support-policy", kind: .web), snippet: "Urgent issues go to the on-call queue."),
        MonarchAiSourceListItem(MonarchAiSourcePart(id: "s3", title: "Ticket 1042", kind: .record, product: "Helpdesk"), isUsed: false),
        MonarchAiSourceListItem(MonarchAiSourcePart(id: "s4", title: "Onboarding checklist.pdf", kind: .file), isUsed: false, snippet: "A list of first-week tasks."),
    ],
    onOpen: { _ in }
)

examples.setup:
private let message = MonarchAiConversationMessage(
    id: "m1",
    role: .assistant,
    parts: [
        .text(MonarchAiTextPart(text: "Revenue grew 12%.")),
        .source(MonarchAiSourcePart(id: "s1", title: "Quarterly planning notes", url: "https://www.example.com/notes/q3", kind: .doc, product: "Docs")),
        .source(MonarchAiSourcePart(id: "s2", title: "Industry report", url: "https://example.org/report", kind: .web)),
    ],
    createdAt: "2024-10-14T10:00:00Z"
)
